//! Computes the position of floats in a block formatting context
//!
//! Here are the precise rules that govern the behavior of floats:
//!
//! 1. The left outer edge of a left-floating box may not be to the left of the left edge of its containing block. An analogous rule
//!    holds for right-floating elements.
//! 2. If the current box is left-floating, and there are any left-floating boxes generated by elements earlier in the source document,
//!    then for each such earlier box, either the left outer edge of the current box must be to the right of the right outer edge of the earlier box,
//!    or its top must be lower than the bottom of the earlier box. Analogous rules hold for right-floating boxes.
//! 3. The right outer edge of a left-floating box may not be to the right of the left outer edge of any right-floating box that is next to it.
//!    Analogous rules hold for right-floating elements.
//! 4. A floating box's outer top may not be higher than the top of its containing block. When the float occurs between two collapsing margins,
//!    the float is positioned as if it had an otherwise empty anonymous block parent taking part in the flow. The position of such a parent is defined
//!    by the rules in the section on margin collapsing.
//! 5. The outer top of a floating box may not be higher than the outer top of any block or floated box generated by an element earlier in the source document.
//! 6. The outer top of an element's floating box may not be higher than the top of any line-box containing a box generated by
//!    an element earlier in the source document.
//! 7. A left-floating box that has another left-floating box to its left may not have its right outer edge to the right of its containing block's
//!    right edge. (Loosely: a left float may not stick out at the right edge, unless it is already as far to the left as possible.) An analogous rule
//!    holds for right-floating elements.
//! 8. A floating box must be placed as high as possible.
//! 9. A left-floating box must be put as far to the left as possible, a right-floating box as far to the right as possible. A higher position is
//!    preferred over one that is further to the left/right.
//!
//! But in CSS 2.2, if, within the block formatting context, there is an in-flow negative vertical margin such that the float's position is above the position it would be at were all such negative margins set to zero, the position of the float is undefined.
//!
//! <https://www.w3.org/TR/CSS22/visuren.html#floats>
//!
//! laffy note: `FloatContext` owns heap lists. It is created with `FloatContext.init(gpa)` and must
//! be freed with `deinit`; the methods that place floats can fail with `error.OutOfMemory`.
const std = @import("std");
const Allocator = std.mem.Allocator;
const geometry = @import("../geometry.zig");
const FloatInsets = geometry.FloatInsets;
const Point = geometry.Point;
const Size = geometry.Size;
const style = @import("../style.zig");
const AvailableSpace = style.AvailableSpace;
const Clear = style.Clear;
const Direction = style.Direction;
const FloatDirection = style.FloatDirection;
const LayoutError = @import("../tree/layout.zig").LayoutError;

/// Tolerance used when checking whether a box fits in a horizontal space, to absorb `f32`
/// rounding errors (e.g. percentage widths and margins that sum to exactly 100% may otherwise
/// exceed the container width and spuriously wrap)
pub const fit_tolerance: f32 = 0.001;

/// An empty "slot" that avoids floats that is suitable for non-floated content
/// to be laid out into
pub const ContentSlot = struct {
    /// The id of the segment that the slot starts in
    segment_id: ?usize = null,
    /// The x position of the start of the slot
    x: f32 = 0.0,
    /// The y position of the start of the slot
    y: f32 = 0.0,
    /// The width of the slot
    width: f32 = 0.0,
    /// The height of the slot
    height: f32 = 0.0,
};

/// An empty "slot" that avoids floats that is suitable for a box that establishes
/// an independent formatting context (and therefore must not overlap floats) to be
/// laid out into. Unlike `ContentSlot`, this accounts for the box's own margins,
/// which are resolved against the containing block's edges (not float edges) and
/// may therefore overlap floats.
pub const BfcSlot = struct {
    /// The id of the segment that the slot starts in
    segment_id: ?usize = null,
    /// The x position of the start of the slot (border box edge)
    x: f32 = 0.0,
    /// The y position of the start of the slot
    y: f32 = 0.0,
    /// The space available for the box's border box: the space between float edges
    /// and the margin-inset containing block edges. The box fits in the slot if its
    /// border box width does not exceed this.
    border_width: f32 = 0.0,
    /// The width that an auto width resolves to (before applying min/max constraints and
    /// the negative-margin lower bound). This differs from `border_width` in that the
    /// trailing margin is subtracted (except for any part of it that overlaps a float).
    stretch_width: f32 = 0.0,
    /// How far down from the slot's top its widths stay valid: a box taller than this may be
    /// beside further floats.
    height: f32 = 0.0,
};

/// A floated box
pub const PlacedFloatedBox = struct {
    /// The caller-defined id that the box was placed with
    id: u64 = 0,
    /// The width of the box
    width: f32 = 0.0,
    /// The height of the box
    height: f32 = 0.0,
    /// Horizontal distance from the edge of the container that the box is floated towards
    /// (distance from the left for left floats, from the right for right floats)
    x_inset: f32 = 0.0,
    /// Vertical distance from top edge of the container
    y: f32 = 0.0,
};

/// A half-open range `start..end` (upstream `core::ops::Range`)
fn Range(comptime T: type) type {
    return struct {
        start: T,
        end: T,

        /// Whether `value` lies in `start..end`
        fn contains(self: @This(), value: T) bool {
            return self.start <= value and value < self.end;
        }
    };
}

/// A non-overlapping horizontal segment of the Block Formatting Context container
const Segment = struct {
    /// The vertical start and end points of the segment
    y: Range(f32),
    /// The space taken up by floats on each side
    insets: FloatInsets,
    /// Whether a float actually occupies the left (slot 0) / right (slot 1) inset.
    /// The insets of a segment created for a float are seeded with the float's containing
    /// block insets on both sides, so a non-zero inset alone does not imply a float.
    has_float: [2]bool,

    /// Whether the segment can fit the passed floated box (in the horizontal axis)
    ///
    /// See `floatFitsHorizontally` for the details of the fit rules.
    fn fitsFloatWidth(
        self: *const Segment,
        floated_box: Size(f32),
        direction: FloatDirection,
        bfc_width: f32,
        cb_insets: FloatInsets,
    ) bool {
        return floatFitsHorizontally(floated_box.width, direction, bfc_width, self.insets, cb_insets);
    }

    /// Widen this segment's float insets and occupied sides to cover `other`'s
    fn @"union"(self: *Segment, other: *const Segment) void {
        self.insets = self.insets.max(other.insets);
        self.has_float = .{ self.has_float[0] or other.has_float[0], self.has_float[1] or other.has_float[1] };
    }

    /// Whether this segment is narrower than `other` on either side: a larger inset, or a float
    /// on a side where `other` has none. The latter counts even if the inset doesn't grow, since
    /// `findBfcSlot` only applies the insets on sides that have a float.
    fn isNarrowerThan(self: *const Segment, other: *const Segment) bool {
        return self.insets.left > other.insets.left or
            self.insets.right > other.insets.right or
            (self.has_float[0] and !other.has_float[0]) or
            (self.has_float[1] and !other.has_float[1]);
    }
};

/// Whether a floated box of the given width fits horizontally given the float insets
/// (`float_insets`) and containing block insets (`cb_insets`) that apply to it.
///
/// A float is normally placed at the further-in of the float edge and the containing block
/// edge on the side it is floated towards (its "lead" side). From that position it must:
///
///   - not overlap any float on the opposite ("trail") side (CSS2 §9.5.1 rule 3), and
///   - not extend past the containing block's trail edge if there is a float on its lead
///     side (CSS2 §9.5.1 rule 7: a float may only stick out of its containing block if it
///     is already as far towards its float direction as possible).
///
/// Note that a float which is not constrained by other floats *may* overflow its
/// containing block's trail edge (rules 1 and 7).
fn floatFitsHorizontally(
    width: f32,
    direction: FloatDirection,
    bfc_width: f32,
    float_insets: FloatInsets,
    cb_insets: FloatInsets,
) bool {
    const lead = direction;
    const trail = direction.opposite();
    const x_inset = @max(inset(float_insets, lead), inset(cb_insets, lead));
    const fits_opposite_floats = inset(float_insets, trail) == 0.0 or
        x_inset + width <= bfc_width - inset(float_insets, trail) + fit_tolerance;
    const fits_containing_block = inset(float_insets, lead) == 0.0 or
        x_inset + width <= bfc_width - inset(cb_insets, trail) + fit_tolerance;
    return fits_opposite_floats and fits_containing_block;
}

/// The inset on the side that a box floated in `direction` is floated towards
/// (upstream `Index<FloatDirection> for FloatInsets`)
pub inline fn inset(insets: FloatInsets, direction: FloatDirection) f32 {
    return switch (direction) {
        .left => insets.left,
        .right => insets.right,
    };
}

/// Mutable access to the inset on the side that a box floated in `direction` is floated towards
/// (upstream `IndexMut<FloatDirection> for FloatInsets`)
pub inline fn insetPtr(insets: *FloatInsets, direction: FloatDirection) *f32 {
    return switch (direction) {
        .left => &insets.left,
        .right => &insets.right,
    };
}

/// Helper type for placing a single floated box
///
/// Given a pinned starting y position, this type helps determine if there is any x position
/// such that there is sufficient horizontal space for the box accross it's entire height.
const FloatFitter = struct {
    /// The overall width of the Block Formatting Context
    bfc_width: f32,
    /// The total height of the set of segments currently being considered
    slot_height: f64,
    /// The union of the float insets of the set of segments currently being considered
    float_insets: FloatInsets,
    /// The insets of the box's containing block from the edges of the Block Formatting Context
    cb_insets: FloatInsets,

    /// Create a new `FloatFitter`
    fn new(bfc_width: f32, slot_height: f32, cb_insets: FloatInsets) FloatFitter {
        return .{ .bfc_width = bfc_width, .slot_height = @floatCast(slot_height), .float_insets = FloatInsets.zero, .cb_insets = cb_insets };
    }

    // Horizontal fitting

    /// Union the insets of another segment. This is a "max" of the insets on each side.
    fn unionInsets(self: *FloatFitter, insets: FloatInsets) void {
        self.float_insets = self.float_insets.max(insets);
    }

    /// The inset from the edge of the BFC (on the side the box is floated towards) that the
    /// box would be placed at given the currently accounted for insets
    fn placedInset(self: *const FloatFitter, direction: FloatDirection) f32 {
        return @max(inset(self.float_insets, direction), inset(self.cb_insets, direction));
    }

    /// Given the currently accounted for insets, check whether there is an x position
    /// such that the box fits horizontally.
    ///
    /// See `floatFitsHorizontally` for the details of the fit rules.
    fn fitsHoriontally(self: *const FloatFitter, width: f32, direction: FloatDirection) bool {
        return floatFitsHorizontally(width, direction, self.bfc_width, self.float_insets, self.cb_insets);
    }

    // Vertical fitting

    /// Add the height of another segment.
    fn addHeight(self: *FloatFitter, height: f32) void {
        self.slot_height += @as(f64, height);
    }

    /// Given the currently accounted for height, check whether the box fits vertically
    fn fitsVertically(self: *const FloatFitter, height: f32) bool {
        return self.slot_height >= @as(f64, height);
    }
};

/// The index of the first segment at or after `hwm` that ends below `min_y`
/// (upstream `segments.get(hwm..).and_then(|s| s.iter().position(..).map(|idx| idx + hwm))`)
fn firstSegmentEndingBelow(segments: []const Segment, hwm: usize, min_y: f32) ?usize {
    if (hwm > segments.len) return null;
    for (segments[hwm..], hwm..) |segment, idx| {
        if (segment.y.end > min_y) return idx;
    }
    return null;
}

/// A context for placing floated boxes
pub const FloatContext = struct {
    /// The allocator the lists below are allocated with (laffy addition)
    gpa: Allocator,
    /// The available space constraint that applies to the root Block Formatting Context
    /// for which this `FloatContext` manages floats.
    available_width: f32 = 0.0,
    /// Whether the float context contains any floats
    has_floats: bool = false,
    /// A list of left-floated boxes within the context
    left_floats: std.ArrayList(PlacedFloatedBox) = .empty,
    /// A list of right-floated boxes within the context
    right_floats: std.ArrayList(PlacedFloatedBox) = .empty,
    /// A list of non-overlapping horizontal "segments" within the context.
    /// Each segment has the same available width for it's entire height.
    segments: std.ArrayList(Segment) = .empty,
    /// A closed-open range indicating which segment the last placed float
    /// was placed(on each side).
    last_placed_floats: [2]Range(usize) = .{ .{ .start = 0, .end = 0 }, .{ .start = 0, .end = 0 } },
    /// The bottom (y + height) of the lowest float placed on each side, including
    /// zero-sized floats (which occupy no segment). Left in slot 0, right in slot 1.
    clear_bottoms: [2]?f32 = .{ null, null },
    /// The topmost y position allowed for a new float (CSS2 float rule 5), including
    /// the tops of zero-sized floats (which occupy no segment)
    float_ceiling: ?f32 = null,

    /// Create a new empty `FloatContext` (upstream `FloatContext::new`)
    pub fn init(gpa: Allocator) FloatContext {
        return .{ .gpa = gpa };
    }

    /// Free the context's lists
    pub fn deinit(self: *FloatContext) void {
        self.left_floats.deinit(self.gpa);
        self.right_floats.deinit(self.gpa);
        self.segments.deinit(self.gpa);
        self.* = undefined;
    }

    /// Whether the float context contains any floats
    pub inline fn hasFloats(self: *const FloatContext) bool {
        return self.has_floats;
    }

    /// Whether the float context contains any floats that extend to or below min_y
    pub inline fn hasActiveFloats(self: *const FloatContext, min_y: f32) bool {
        const segments = self.segments.items;
        return self.has_floats and segments.len > 0 and segments[segments.len - 1].y.end > min_y;
    }

    /// Set the width of the `FloatContext`
    pub fn setWidth(self: *FloatContext, available_width: f32) void {
        self.available_width = available_width;
    }

    /// Returns a slice of placed left floats
    pub fn leftFloats(self: *const FloatContext) []const PlacedFloatedBox {
        return self.left_floats.items;
    }

    /// Returns a slice of placed right floats
    pub fn rightFloats(self: *const FloatContext) []const PlacedFloatedBox {
        return self.right_floats.items;
    }

    /// Divide a segment into two segments so that a new float can be placed and have it's
    /// vertical start and end at exact segment boundaries
    fn subdivideSegment(self: *FloatContext, idx: usize, divide_at_y: f32) LayoutError!void {
        const old_segment = &self.segments.items[idx];
        const new_segment: Segment = .{
            .insets = old_segment.insets,
            .has_float = old_segment.has_float,
            .y = .{ .start = divide_at_y, .end = old_segment.y.end },
        };
        std.debug.assert(old_segment.y.contains(divide_at_y) and old_segment.y.start != divide_at_y);
        old_segment.y.end = divide_at_y;

        try self.segments.insert(self.gpa, idx + 1, new_segment);
    }

    /// The (x, y) coordinates of a box previously placed in the context on the `direction` side
    pub fn placedPosition(self: *const FloatContext, placed: *const PlacedFloatedBox, direction: FloatDirection) Point(f32) {
        return switch (direction) {
            .left => .{ .x = placed.x_inset, .y = placed.y },
            .right => .{ .x = self.available_width - placed.x_inset - placed.width, .y = placed.y },
        };
    }

    /// Update the last placed float start and end values
    fn updateLastPlacedFloat(self: *FloatContext, direction: FloatDirection, placement: Range(usize)) void {
        const slot = @backingInt(direction);
        self.last_placed_floats[slot].start = @max(self.last_placed_floats[slot].start, placement.start);
        self.last_placed_floats[slot].end = @max(self.last_placed_floats[slot].end, placement.end);
    }

    /// Position a floated box with the context, returning the (x, y) coordinates.
    /// `id` is stored with the placed box and is not otherwise interpreted.
    pub fn placeFloatedBox(
        self: *FloatContext,
        id: u64,
        floated_box: Size(f32),
        min_y: f32,
        containing_block_insets: FloatInsets,
        direction: FloatDirection,
        clear: Clear,
    ) LayoutError!Point(f32) {
        self.has_floats = true;

        // Reserve space up front so that the box is recorded even if pushing it would fail
        // after the segments have been updated
        switch (direction) {
            .left => try self.left_floats.ensureUnusedCapacity(self.gpa, 1),
            .right => try self.right_floats.ensureUnusedCapacity(self.gpa, 1),
        }

        const placed_floated_box = try self.placeFloatedBoxInner(id, floated_box, min_y, containing_block_insets, direction, clear);

        const slot = @backingInt(direction);
        const bottom = placed_floated_box.y + placed_floated_box.height;
        self.clear_bottoms[slot] = if (self.clear_bottoms[slot]) |b| @max(b, bottom) else bottom;
        const y = placed_floated_box.y;
        self.float_ceiling = if (self.float_ceiling) |ceiling| @max(ceiling, y) else y;

        const pos = self.placedPosition(&placed_floated_box, direction);
        switch (direction) {
            .left => self.left_floats.appendAssumeCapacity(placed_floated_box),
            .right => self.right_floats.appendAssumeCapacity(placed_floated_box),
        }
        return pos;
    }

    /// Inner implementation of float placement, split into a separate function so that it can early-return
    fn placeFloatedBoxInner(
        self: *FloatContext,
        id: u64,
        floated_box: Size(f32),
        min_y_in: f32,
        containing_block_insets: FloatInsets,
        direction: FloatDirection,
        clear: Clear,
    ) LayoutError!PlacedFloatedBox {
        const slot = @backingInt(direction);
        const neg_inf = -std.math.inf(f32);

        // Floats (including zero-sized floats) that occupy no segment still constrain the
        // position of later boxes: rule 5 (a float may not be higher than the top of any
        // earlier float) and `clear` (which clears past the bottom of floats on the
        // relevant side, regardless of their width)
        const min_y = @max(@max(min_y_in, self.float_ceiling orelse neg_inf), self.clearedThreshold(clear) orelse neg_inf);

        // Ensure that float:
        //    - Starts at or after the last placed float in either direction (CSS2 float rule 5:
        //      "The outer top of a floating box may not be higher than the outer top of any block
        //      or floated box generated by an element earlier in the source document")
        //    - Respects "clear"
        const float_start = @max(self.last_placed_floats[0].start, self.last_placed_floats[1].start);
        const hwm = switch (clear) {
            .left => blk: {
                const left_end = self.last_placed_floats[0].end;
                break :blk @max(float_start, left_end + 1);
            },
            .right => blk: {
                const right_end = self.last_placed_floats[1].end;
                break :blk @max(float_start, right_end + 1);
            },
            .both => blk: {
                const left_end = self.last_placed_floats[0].end;
                const right_end = self.last_placed_floats[1].end;
                break :blk @max(left_end, right_end) + 1;
            },
            .none => float_start,
        };

        // Ensure that float is placed in a segment at or below "min_y"
        // (ensuring that it is placed at or below min_y within it's segment happens below)
        var start_idx = firstSegmentEndingBelow(self.segments.items, hwm, min_y) orelse self.segments.items.len;
        var start_y = min_y;
        var end_idx = start_idx;

        // Loop over remaining segments, trying to place the float in a position
        // that has space to accomodate it.
        const Found = struct { start: ?usize, end: ?usize, placed_inset: f32 };
        const found: Found = found: {
            outer: while (true) {
                // Start segment does not exist:
                //
                // This means no existing segment can accomodate the float so we must create a new
                // segment below all existing segments. A new segment will always have space for
                // the float, so we can exit the loop at this point.
                if (start_idx >= self.segments.items.len) {
                    break :found .{ .start = null, .end = null, .placed_inset = inset(containing_block_insets, direction) };
                }
                const start_segment = self.segments.items[start_idx];

                // Candidate start segment doesn't have (horizontal) space for the float:
                // => retry with the next segment
                if (!start_segment.fitsFloatWidth(floated_box, direction, self.available_width, containing_block_insets)) {
                    start_idx += 1;
                    end_idx = @max(end_idx, start_idx);
                    continue;
                }

                start_y = @max(start_y, start_segment.y.start);
                const available_height = start_segment.y.end - start_y;
                var fitter = FloatFitter.new(self.available_width, available_height, containing_block_insets);
                fitter.unionInsets(start_segment.insets);

                // Pinning the start segment, loop over segments starting with the start segment
                // to find the end segment:
                //   - The selected segment range must have enough height to contain the float
                //   - All of the segments in the range must have enough horizontal width to contain the float
                //     TODO: must ensure that width is in the correct place.
                while (true) {
                    // End segment does not exist:
                    //
                    // This means no existing segment can accomodate the float so we must create a new
                    // segment below all existing segments
                    if (end_idx >= self.segments.items.len) {
                        const placed = fitter.placedInset(direction);
                        break :found .{ .start = start_idx, .end = null, .placed_inset = placed };
                    }
                    const end_segment = self.segments.items[end_idx];

                    // Check horizontal fit
                    //
                    // If it does not fit horizontally then it will never fit in this position, so
                    // continue the outer loop to find and check a new position
                    fitter.unionInsets(end_segment.insets);
                    if (!fitter.fitsHoriontally(floated_box.width, direction)) {
                        start_idx += 1;
                        end_idx = @max(end_idx, start_idx);
                        continue :outer;
                    }

                    // Check vertical fit
                    //
                    // If it does not (yet) fit vertically then continue the inner loop to add another
                    // segment to the range of segments we are placing the float in
                    if (end_idx != start_idx) {
                        fitter.addHeight(end_segment.y.end - end_segment.y.start);
                    }
                    if (!fitter.fitsVertically(floated_box.height)) {
                        end_idx += 1;
                        continue;
                    }

                    const placed = fitter.placedInset(direction);
                    break :found .{ .start = start_idx, .end = end_idx, .placed_inset = placed };
                }
            }
        };
        var end = found.end;
        const placed_inset = found.placed_inset;

        // Handle case where floated box is placed after all existing segments
        if (found.start == null) {
            // Before the first float, the context is float-free all the way up: the first float
            // gets an empty segment above it like any other float placed below all segments, so
            // that content positioned above it (e.g. by a negative margin) is not moved down to
            // it. The first float itself may be above the top of the block formatting context
            // (`y < 0`): its containing block (CSS2 float rule 4) may be pulled up by a negative
            // margin.
            const last_y_end = if (self.segments.items.len > 0) self.segments.items[self.segments.items.len - 1].y.end else neg_inf;
            if (start_y > last_y_end) {
                try self.segments.append(self.gpa, .{
                    .y = .{ .start = last_y_end, .end = start_y },
                    .insets = FloatInsets.zero,
                    .has_float = .{ false, false },
                });
            }

            const new_start_y = @max(last_y_end, start_y);

            var insets = containing_block_insets;
            insetPtr(&insets, direction).* += floated_box.width;
            var has_float: [2]bool = .{ false, false };
            has_float[slot] = true;
            try self.segments.append(self.gpa, .{ .y = .{ .start = new_start_y, .end = new_start_y + floated_box.height }, .insets = insets, .has_float = has_float });

            // Update last_placed_float
            const new_start_idx = self.segments.items.len - 1;
            const new_end_idx = new_start_idx + 1;
            self.updateLastPlacedFloat(direction, .{ .start = new_start_idx, .end = new_end_idx });

            return .{
                .id = id,
                .width = floated_box.width,
                .height = floated_box.height,
                .y = new_start_y,
                .x_inset = inset(containing_block_insets, direction),
            };
        }

        // Else unwrap the index of the segment that the start of the floating box is placed in
        start_idx = found.start.?;

        // If the floated box doesn't start at the exact same y-offset as the segment it starts in, then
        // subdivide that segment into two segments at the y-offset that the floated box starts at, and increment
        // `start_idx` so that the floating box is placed in the second of the two segments.
        if (start_y != self.segments.items[start_idx].y.start) {
            try self.subdivideSegment(start_idx, start_y);
            start_idx += 1;
            if (end) |*e| e.* += 1;
        }

        // A zero-height float takes up no vertical space, but still narrows content and floats
        // whose vertical extent crosses its position, so it gets its own zero-height segment
        if (floated_box.height == 0.0) {
            var segment = self.segments.items[start_idx];
            segment.y = .{ .start = start_y, .end = start_y };
            try self.segments.insert(self.gpa, start_idx, segment);
            end = start_idx;
        }

        const final_end_idx = if (end) |end_idx_in| blk: {
            var e = end_idx_in;
            const end_y = start_y + floated_box.height;

            // Due to floating point imprecision, `end_y` may coincide with (or fall before)
            // the start of the end segment even though the sum of the candidate segment
            // heights was computed as sufficient. In that case the float effectively ends at
            // the boundary of the previous segment, so walk back to the segment that actually
            // contains `end_y`.
            while (e > start_idx and end_y <= self.segments.items[e].y.start) {
                e -= 1;
            }

            // Only subdivide if `end_y` falls strictly within the segment. If it lands on
            // (or, due to floating point imprecision, beyond) a segment boundary then no
            // subdivision is needed.
            if (self.segments.items[e].y.start < end_y and end_y < self.segments.items[e].y.end) {
                try self.subdivideSegment(e, end_y);
            }

            break :blk e;
        } else blk: {
            // The float extends below all existing segments: add a segment for the part of it
            // below the last segment (its insets are set along with the other segments below)
            const last_y_end = self.segments.items[self.segments.items.len - 1].y.end;
            const end_y = start_y + floated_box.height;
            if (end_y > last_y_end) {
                const insets = containing_block_insets;
                try self.segments.append(self.gpa, .{ .y = .{ .start = last_y_end, .end = end_y }, .insets = insets, .has_float = .{ false, false } });
            }
            break :blk self.segments.items.len - 1;
        };

        // Update inset for the range of segments that the float is placed in
        const placed_inset_plus_width = placed_inset + floated_box.width;
        for (self.segments.items[start_idx .. final_end_idx + 1]) |*segment| {
            insetPtr(&segment.insets, direction).* = placed_inset_plus_width;
            segment.has_float[slot] = true;
        }

        // Update last_placed_float
        self.updateLastPlacedFloat(direction, .{ .start = start_idx, .end = final_end_idx + 1 });

        return .{ .id = id, .width = floated_box.width, .height = floated_box.height, .y = start_y, .x_inset = placed_inset };
    }

    /// Get the end segment of the last float on side(s) specified by the clear parameter (if any)
    ///
    /// Returns `null` if no float has been placed on the relevant side(s)
    fn clearedSegment(self: *const FloatContext, clear: Clear) ?usize {
        const left_end = self.last_placed_floats[0].end;
        const right_end = self.last_placed_floats[1].end;
        return switch (clear) {
            .left => if (left_end > 0) left_end else null,
            .right => if (right_end > 0) right_end else null,
            .both => if (left_end > 0 or right_end > 0) @max(left_end, right_end) else null,
            .none => null,
        };
    }

    /// Get the bottom of lowest relevant float for the specific clear property
    pub fn clearedThreshold(self: *const FloatContext, clear: Clear) ?f32 {
        return switch (clear) {
            .left => self.clear_bottoms[0],
            .right => self.clear_bottoms[1],
            .both => if (self.clear_bottoms[0]) |l|
                (if (self.clear_bottoms[1]) |r| @max(l, r) else l)
            else
                self.clear_bottoms[1],
            .none => null,
        };
    }

    /// Search for a space suitable for laying out non-floated content into
    ///
    /// The returned slot avoids the floats beside any part of `height` below its top edge (a line
    /// box is shortened by every float its vertical extent intersects). The slot's `height` is
    /// how far down from its top edge its width stays valid: content taller than that may be
    /// beside further floats.
    pub fn findContentSlot(
        self: *const FloatContext,
        min_y_in: f32,
        height: f32,
        containing_block_insets: FloatInsets,
        clear: Clear,
        after: ?usize,
    ) ContentSlot {
        // Subtract each inset separately (here and below): `- insets.sum()` rounds differently for large values
        if (!self.hasActiveFloats(min_y_in)) {
            return .{
                .segment_id = null,
                .x = containing_block_insets.left,
                .y = min_y_in,
                .width = self.available_width - containing_block_insets.left - containing_block_insets.right,
                .height = std.math.inf(f32),
            };
        }

        // Clearance clears past the bottom of floats on the relevant side, including
        // zero-sized floats which occupy no segment
        const min_y = @max(min_y_in, self.clearedThreshold(clear) orelse -std.math.inf(f32));

        // The min starting segment index
        const at_least = if (after) |idx| idx + 1 else 0;
        const hwm = @max(at_least, if (self.clearedSegment(clear)) |idx| idx + 1 else 0);

        const segments = self.segments.items;
        const start_idx = firstSegmentEndingBelow(segments, hwm, min_y) orelse segments.len;
        if (start_idx < segments.len) {
            const segment = segments[start_idx];
            const y = @max(segment.y.start, min_y);
            const end_y = y + height;

            // Combine the insets of every segment beside the content's height, then extend
            // the slot down over any further segments that don't narrow it
            var insets = containing_block_insets.max(segment.insets);
            var slot_height = std.math.inf(f32);
            for (segments[start_idx + 1 ..]) |lower| {
                if (lower.y.start < end_y) {
                    insets = insets.max(lower.insets);
                } else if (lower.insets.left > insets.left or lower.insets.right > insets.right) {
                    slot_height = lower.y.start - y;
                    break;
                }
            }

            return .{
                .segment_id = start_idx,
                .x = insets.left,
                .y = y,
                .width = self.available_width - insets.left - insets.right,
                .height = slot_height,
            };
        } else {
            return .{
                .segment_id = null,
                .x = containing_block_insets.left,
                .y = min_y,
                .width = self.available_width - containing_block_insets.left - containing_block_insets.right,
                .height = std.math.inf(f32),
            };
        }
    }

    /// Search for a space suitable for laying out a box that establishes an independent
    /// formatting context (whose border box must not overlap floats).
    ///
    /// The box's margins are resolved against the containing block's content edges. When there
    /// are floats beside the box:
    ///
    ///   - The leading margin (in flow direction) positions the border box's leading edge, but
    ///     may be partially or fully "absorbed" by a float on the leading side (the border edge
    ///     is the further-in of the float edge and the margin-inset containing block edge), and
    ///     a negative leading margin does not move the border edge past the float edge. When no
    ///     float intrudes on the leading side the margin applies as usual, and a negative margin
    ///     may move the border edge outside the containing block.
    ///   - The trailing margin is subtracted from the width an auto width resolves to (except
    ///     for any part of it that overlaps a float on the trailing side). When a float intrudes
    ///     on the trailing side, the trailing margin does not affect whether a box of a given
    ///     width fits in the slot: the trailing margin may overflow the containing block edge.
    ///     When no float intrudes on the trailing side the margin applies as usual, and a
    ///     negative margin lets the border box extend outside the containing block.
    ///
    /// When there are no floats beside the box, its (possibly negative) margins apply as usual.
    ///
    /// The box must not overlap floats beside any part of `min_height` (a lower bound on the
    /// height of its border box) below its top edge: e.g. a box pulled up above a float by a
    /// negative top margin may only stay there if it also fits beside that float.
    pub fn findBfcSlot(
        self: *const FloatContext,
        min_y_in: f32,
        min_height: f32,
        containing_block_insets: FloatInsets,
        margins: FloatInsets,
        direction: Direction,
        clear: Clear,
        after: ?usize,
    ) BfcSlot {
        const margin_insets = containing_block_insets.add(margins);
        const no_float_width = self.available_width - margin_insets.left - margin_insets.right;
        const no_float_slot: BfcSlot = .{
            .segment_id = null,
            .x = margin_insets.left,
            .y = min_y_in,
            .border_width = no_float_width,
            .stretch_width = no_float_width,
            .height = std.math.inf(f32),
        };

        if (!self.hasActiveFloats(min_y_in)) {
            return no_float_slot;
        }

        // Clearance clears past the bottom of floats on the relevant side, including
        // zero-sized floats which occupy no segment
        const min_y = @max(min_y_in, self.clearedThreshold(clear) orelse -std.math.inf(f32));

        // The min starting segment index
        const at_least = if (after) |idx| idx + 1 else 0;
        const hwm = @max(at_least, if (self.clearedSegment(clear)) |idx| idx + 1 else 0);

        const segments = self.segments.items;
        const start_idx = firstSegmentEndingBelow(segments, hwm, min_y) orelse segments.len;
        if (start_idx < segments.len) {
            const segment = segments[start_idx];
            const y = @max(segment.y.start, min_y);

            // Combine the float insets of every segment beside the box's minimum height, then
            // extend the slot down over any further segments that don't narrow it
            var combined = segment;
            var lower_idx = start_idx + 1;
            while (lower_idx < segments.len and segments[lower_idx].y.start < y + min_height) : (lower_idx += 1) {
                combined.@"union"(&segments[lower_idx]);
            }
            var slot_height = std.math.inf(f32);
            for (segments[lower_idx..]) |*lower| {
                if (lower.isNarrowerThan(&combined)) {
                    slot_height = lower.y.start - y;
                    break;
                }
            }
            const insets = combined.insets;
            const has_float = combined.has_float;

            const lead: FloatDirection = switch (direction) {
                .ltr => .left,
                .rtl => .right,
            };
            const trail = lead.opposite();
            const has_lead_float = has_float[@backingInt(lead)];
            const has_trail_float = has_float[@backingInt(trail)];
            var fit_insets = FloatInsets.zero;
            var stretch_insets = FloatInsets.zero;
            insetPtr(&fit_insets, lead).* = if (has_lead_float)
                @max(inset(insets, lead), inset(margin_insets, lead))
            else
                inset(margin_insets, lead);
            insetPtr(&stretch_insets, lead).* = inset(fit_insets, lead);
            insetPtr(&fit_insets, trail).* = if (has_trail_float)
                @max(inset(insets, trail), inset(containing_block_insets, trail))
            else
                // A positive trailing margin may overflow the containing block edge (it does
                // not affect fit), but a negative one widens the space for the border box
                @min(inset(margin_insets, trail), inset(containing_block_insets, trail));
            insetPtr(&stretch_insets, trail).* = if (has_trail_float)
                @max(inset(insets, trail), inset(margin_insets, trail))
            else
                inset(margin_insets, trail);
            return .{
                .segment_id = start_idx,
                .x = fit_insets.left,
                .y = y,
                .border_width = self.available_width - fit_insets.left - fit_insets.right,
                .stretch_width = self.available_width - stretch_insets.left - stretch_insets.right,
                .height = slot_height,
            };
        } else {
            // Below all floats
            var slot = no_float_slot;
            slot.y = @max(if (segments.len > 0) segments[segments.len - 1].y.end else min_y, min_y);
            return slot;
        }
    }
};

/// Context for computing the intrinsic width contribution of a set of floats
pub const FloatIntrinsicWidthCalculator = struct {
    /// The available width of the container
    available_width: AvailableSpace,
    /// The running sums of the widths of adjacent uncleared floats on each side (left, right)
    side_sums: [2]f32,
    /// The running total intrinsic width contribution
    contribution: f32,
    /// The widest single float (the floats' min-content contribution)
    widest: f32,

    /// Create a new `FloatIntrinsicWidthCalculator`
    pub fn new(available_width: AvailableSpace) FloatIntrinsicWidthCalculator {
        return .{ .available_width = available_width, .side_sums = .{ 0.0, 0.0 }, .contribution = 0.0, .widest = 0.0 };
    }

    /// Add a float to the computation
    pub fn addFloat(self: *FloatIntrinsicWidthCalculator, width: f32, direction: FloatDirection, clear: Clear) void {
        switch (self.available_width) {
            // Definite available width means the container is being fit-content sized
            // (e.g. it is itself a float being shrink-to-fit sized). The floats' max-content
            // contribution (widths summed) is clamped by the available width in `result`.
            .definite, .max_content => {
                // A float that clears a side is placed below the floats on that side, so its
                // width does not accumulate with theirs.
                if (clear == .left or clear == .both) {
                    self.side_sums[0] = 0.0;
                }
                if (clear == .right or clear == .both) {
                    self.side_sums[1] = 0.0;
                }
                self.side_sums[@backingInt(direction)] += width;
                self.contribution = @max(self.contribution, self.side_sums[0] + self.side_sums[1]);
            },
            .min_content => self.contribution = @max(self.contribution, width),
        }
        self.widest = @max(self.widest, width);
    }

    /// Get the computed float contribution to intrinsic width
    pub fn result(self: *const FloatIntrinsicWidthCalculator) f32 {
        return switch (self.available_width) {
            // Fit-content sizing: clamp the max-content contribution between the available
            // width and the min-content contribution (floats narrow by wrapping onto new
            // bands, but never below the widest single float).
            .definite => |available_width| @max(@min(self.contribution, available_width), self.widest),
            else => self.contribution,
        };
    }
};

// ---------------------------------------------------------------------------------------------
// Tests (laffy additions: upstream has no unit tests for this module)

const testing = std.testing;

test "floats stack horizontally then wrap below" {
    var ctx = FloatContext.init(testing.allocator);
    defer ctx.deinit();
    ctx.setWidth(100.0);
    try testing.expect(!ctx.hasFloats());

    const a = try ctx.placeFloatedBox(1, .{ .width = 40.0, .height = 10.0 }, 0.0, FloatInsets.zero, .left, .none);
    try testing.expectEqual(Point(f32){ .x = 0.0, .y = 0.0 }, a);
    const b = try ctx.placeFloatedBox(2, .{ .width = 30.0, .height = 20.0 }, 0.0, FloatInsets.zero, .right, .none);
    try testing.expectEqual(Point(f32){ .x = 70.0, .y = 0.0 }, b);
    // Does not fit beside both: placed below the left float, still beside the right float
    const c = try ctx.placeFloatedBox(3, .{ .width = 50.0, .height = 5.0 }, 0.0, FloatInsets.zero, .left, .none);
    try testing.expectEqual(Point(f32){ .x = 0.0, .y = 10.0 }, c);
    // Clearing both sides moves it below everything
    const d = try ctx.placeFloatedBox(4, .{ .width = 10.0, .height = 5.0 }, 0.0, FloatInsets.zero, .left, .both);
    try testing.expectEqual(Point(f32){ .x = 0.0, .y = 20.0 }, d);

    try testing.expect(ctx.hasActiveFloats(24.0));
    try testing.expect(!ctx.hasActiveFloats(25.0));
    try testing.expectEqual(@as(?f32, 25.0), ctx.clearedThreshold(.left));
    try testing.expectEqual(@as(?f32, 20.0), ctx.clearedThreshold(.right));
    try testing.expectEqual(@as(?f32, 25.0), ctx.clearedThreshold(.both));
    try testing.expectEqual(@as(?f32, null), ctx.clearedThreshold(.none));
    try testing.expectEqual(@as(usize, 3), ctx.leftFloats().len);
    try testing.expectEqual(@as(u64, 2), ctx.rightFloats()[0].id);

    const content = ctx.findContentSlot(0.0, 1.0, FloatInsets.zero, .none, null);
    try testing.expectEqual(@as(f32, 40.0), content.x);
    try testing.expectEqual(@as(f32, 30.0), content.width);
    const below = ctx.findContentSlot(0.0, 1.0, FloatInsets.zero, .both, null);
    try testing.expectEqual(@as(f32, 25.0), below.y);
    try testing.expectEqual(@as(f32, 100.0), below.width);

    const bfc = ctx.findBfcSlot(0.0, 0.0, FloatInsets.zero, FloatInsets.new(5.0, 35.0), .ltr, .none, null);
    try testing.expectEqual(@as(f32, 40.0), bfc.x);
    try testing.expectEqual(@as(f32, 30.0), bfc.border_width);
    try testing.expectEqual(@as(f32, 25.0), bfc.stretch_width);
}

test "zero-height floats and intrinsic widths" {
    var ctx = FloatContext.init(testing.allocator);
    defer ctx.deinit();
    ctx.setWidth(50.0);
    _ = try ctx.placeFloatedBox(1, .{ .width = 20.0, .height = 30.0 }, 0.0, FloatInsets.zero, .left, .none);
    const z = try ctx.placeFloatedBox(2, .{ .width = 10.0, .height = 0.0 }, 5.0, FloatInsets.zero, .left, .none);
    try testing.expectEqual(Point(f32){ .x = 20.0, .y = 5.0 }, z);
    const r = try ctx.placeFloatedBox(3, .{ .width = 10.0, .height = 10.0 }, 0.0, FloatInsets.zero, .right, .none);
    try testing.expectEqual(Point(f32){ .x = 40.0, .y = 5.0 }, r);

    var calc = FloatIntrinsicWidthCalculator.new(.max_content);
    calc.addFloat(10.0, .left, .none);
    calc.addFloat(20.0, .right, .none);
    calc.addFloat(5.0, .left, .left);
    try testing.expectEqual(@as(f32, 30.0), calc.result());
    var fit = FloatIntrinsicWidthCalculator.new(.{ .definite = 12.0 });
    fit.addFloat(10.0, .left, .none);
    fit.addFloat(20.0, .left, .none);
    try testing.expectEqual(@as(f32, 20.0), fit.result());
    var min = FloatIntrinsicWidthCalculator.new(.min_content);
    min.addFloat(10.0, .left, .none);
    min.addFloat(7.0, .right, .none);
    try testing.expectEqual(@as(f32, 10.0), min.result());
}
